package com.example.starter.maintenance.domain;

import java.time.Instant;

/**
 * 能源隔离令。
 *
 * @param orderId        隔离令唯一标识
 * @param equipmentId    所属设备标识
 * @param state          状态：PENDING 待双角色确认 / ISOLATED 隔离生效 / RELEASED 已解除
 * @param createdBy      创建操作者（创建时固化）
 * @param createdAt      创建时刻（UTC）
 * @param effectiveAt    生效时刻（UTC），未生效为 null
 * @param releasedAt     解除时刻（UTC），未解除为 null
 * @param releasedBy     解除操作者，未解除为 null
 * @param releaseReason  解除原因（令级），未解除为 null
 */
public record IsolationOrder(
        String orderId,
        String equipmentId,
        String state,
        String createdBy,
        Instant createdAt,
        Instant effectiveAt,
        Instant releasedAt,
        String releasedBy,
        String releaseReason) {

    public static final String PENDING = "PENDING";
    public static final String ISOLATED = "ISOLATED";
    public static final String RELEASED = "RELEASED";
}

package com.example.starter.maintenance.domain;

import java.time.Instant;
import java.util.List;

/**
 * 隔离锁定点快照及其确认/解除状态。
 *
 * @param seqNo          隔离令内规范化顺序（从 1 开始）
 * @param pointId        锁定点业务标识（创建后固化）
 * @param confirmations  已发生的角色确认（取自 lock_event，按角色升序）
 * @param releasedAt     该点解除时刻（UTC），未解除为 null
 * @param releasedBy     该点解除操作人，未解除为 null
 * @param releaseReason  该点解除原因，未解除为 null
 */
public record LockPoint(
        int seqNo,
        String pointId,
        List<LockConfirmation> confirmations,
        Instant releasedAt,
        String releasedBy,
        String releaseReason) {

    public boolean confirmedBy(String role) {
        return confirmations.stream().anyMatch(c -> c.role().equals(role));
    }
}

package com.example.starter.maintenance.domain;

import java.time.Instant;

/**
 * 锁定点的一次角色确认证据。
 *
 * @param role       维护角色：ELECTRICIAN 电气 / MECHANIC 机械
 * @param operator   确认操作人
 * @param confirmedAt 确认时刻（UTC）
 */
public record LockConfirmation(String role, String operator, Instant confirmedAt) {

    public static final String ELECTRICIAN = "ELECTRICIAN";
    public static final String MECHANIC = "MECHANIC";
}

