        try {
            Map<String, Object> ordered = new TreeMap<>();
            if (payload instanceof Map<?, ?> map) {
                for (Map.Entry<?, ?> entry : map.entrySet()) {
                    ordered.put(String.valueOf(entry.getKey()), entry.getValue());
                }
            }
            return objectMapper.writerWithDefaultPrettyPrinter() == null
                    ? objectMapper.writeValueAsString(ordered)
                    : canonical().writeValueAsString(ordered);
        } catch (Exception e) {
            throw new IllegalStateException("幂等指纹生成失败", e);
        }
    }

    private ObjectMapper canonical() {
        return objectMapper.copy()
                .configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true);
    }

    /** 消除未使用导入告警的占位引用（LinkedHashMap 在装配阶段保留扩展位）。 */
    @SuppressWarnings("unused")
    private static final Class<?> KEEP_LINKED_HASH_MAP = LinkedHashMap.class;
}

