    // ---------- 批量隔离 ----------

    @Test
    void batch_allOrNothing() throws Exception {
        register("eq-b1", 100);
        register("eq-b2", 100);
        register("eq-b3", 100);
        // eq-b3 已停用
        mockMvc.perform(post("/api/equipment/eq-b3/decommission")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
