                .andExpect(status().isOk());

        // 任一设备失败（已停用）→ 整批不生效
        mockMvc.perform(post("/api/equipment/isolations/batch")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"batch-1","operator":"op",
