                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.createdCount").value(2))
                .andExpect(jsonPath("$.requiredCount").value(2))
                .andExpect(jsonPath("$.orders[0].equipmentId").value("eq-b1"))
