private static List<String> normalizeDistinctPoints(List<String> pointIds, String equipmentId,
                                                    String orderId) {
    List<String> sorted = pointIds.stream().sorted().toList();
    for (int i = 1; i < sorted.size(); i++) {
        if (sorted.get(i).equals(sorted.get(i - 1))) {
            throw ApiException.unprocessable("LOCK_POINT_DUPLICATE",
                    "隔离令 " + orderId + "（设备 " + equipmentId + "）锁定点重复：" + sorted.get(i));
        }
    }
    return sorted;
}

